/* eslint-disable */
/* global WebImporter */

/**
 * Parser: vehicle-search (block table "Vehicle Search").
 * Source: https://www.amag.ch/de/garagenuebersicht/garage-buelach.html — `.amag-dspSearch`.
 *
 * Authoring rows (blocks/vehicle-search/vehicle-search.js, read by role):
 *   - head row:    <p><img icon></p> <h2>headline</h2> <p>intro</p>
 *   - picker rows: <p>label</p> | <ul><li>option</li>…</ul>  (first <li> = shown value)
 *   - CTA row:     <p><em><a href>Auto finden</a></em></p>  (search glyph generated by the block)
 *
 * Options are read from the native <select> of each filter (`.amag-dspSearch__filter select`)
 * — the source renders a second, JS-built dropdown copy of the same lists (hidden model
 * entries included) and a duplicate search button; both duplicates are ignored.
 * Dropped: picker chevrons and the CTA's inline search glyph (re-created by the block).
 */
const ORIGIN = 'https://www.amag.ch';
const txt = (n) => (n ? n.textContent.replace(/\s+/g, ' ').trim() : '');
const abs = (u) => {
  if (!u) return '';
  const s = u.trim();
  if (/^(data:|https?:)/i.test(s)) return s;
  if (s.startsWith('//')) return `https:${s}`;
  try { return new URL(s, `${ORIGIN}/`).href; } catch (e) { return s; }
};
const mk = (document, tag, ...kids) => {
  const e = document.createElement(tag);
  kids.flat().forEach((k) => { if (k != null && k !== '') e.append(k); });
  return e;
};

export default function parse(element, { document }) {
  const cells = [];

  // Head row.
  const head = [];
  const iconSrc = element.querySelector('.amag-dspSearch__icon img');
  if (iconSrc && iconSrc.getAttribute('src')) {
    const img = document.createElement('img');
    img.setAttribute('src', abs(iconSrc.getAttribute('src')));
    img.setAttribute('alt', (iconSrc.getAttribute('alt') || '').trim());
    head.push(mk(document, 'p', img));
  }
  const h = element.querySelector('.amag-dspSearch__headline h2, .amag-dspSearch__headline h1, .amag-dspSearch__headline h3, h2');
  if (h) head.push(mk(document, 'h2', txt(h)));
  element.querySelectorAll('.amag-dspSearch__introText p').forEach((p) => {
    if (txt(p)) head.push(mk(document, 'p', txt(p)));
  });
  if (head.length) cells.push([head]);

  // Picker rows from the native selects (one per filter wrapper).
  let wrappers = [...element.querySelectorAll('.amag-dspSearch__filter .select2-wrapper')];
  if (!wrappers.length) wrappers = [...element.querySelectorAll('select')].map((s) => s.parentElement);
  wrappers.forEach((w) => {
    const select = w.querySelector('select');
    const label = txt(w.querySelector('label'));
    if (!select) return;
    const options = [...select.querySelectorAll('option')].map((o) => txt(o)).filter(Boolean);
    if (!options.length) return;
    const ul = mk(document, 'ul', options.map((o) => mk(document, 'li', o)));
    cells.push([mk(document, 'p', label), ul]);
  });

  // CTA row (first search button; the second is a responsive duplicate).
  const cta = element.querySelector('.amag-dspSearch__searchButton a[href]');
  if (cta && txt(cta)) {
    const a = mk(document, 'a', txt(cta));
    a.setAttribute('href', cta.getAttribute('href'));
    cells.push([mk(document, 'p', mk(document, 'em', a))]);
  }

  if (!h && cells.length < 2) {
    element.replaceWith(...element.childNodes);
    return;
  }

  const block = WebImporter.Blocks.createBlock(document, { name: 'Vehicle Search', cells });
  element.replaceWith(block);
}
